@@ -86,7 +87,12 @@ class PoolBase extends DispatcherBase {
         break
       }
       this[kQueued]--
-      needDrain = !item.dispatch(client)
+      // dispatch() returning false is backpressure, but for a real Client a
+      // synchronous validation error (e.g. an invalid header) also returns
+      // false without enqueuing a request. In that case the client is not
+      // saturated and will never emit a drain event, so only stop when the
+      // client is actually busy.
+      needDrain = !item.dispatch(client) && (client[kBusy] === undefined || client[kBusy])
     }

     client[kNeedDrain] = needDrain
@@ -117,6 +123,23 @@ class PoolBase extends DispatcherBase {

   [kOnClientDrain] () {}

+  // dispatch() returning false is treated as backpressure: the client is full
+  // and will emit a drain event once it frees up. For a real Client, a
+  // synchronous validation error (e.g. an invalid header) also makes
+  // dispatch() return false via DispatcherBase#dispatch, but the request was
+  // never enqueued, so the client is not saturated and will never emit a
+  // drain event to clear the flag. Marking such a client as needing drain
+  // would leave it (and any queued requests behind it) stalled forever. Only
+  // mark a client when it is genuinely busy; custom dispatchers that do not
+  // implement [kBusy] expose no such signal, so we conservatively treat
+  // false as backpressure for them.
+  [kMarkBusy] (dispatcher) {
+    if (dispatcher[kBusy] === undefined || dispatcher[kBusy]) {
+      dispatcher[kNeedDrain] = true
+      this[kOnClientBusy](dispatcher)
+    }
+  }
+
   [kDrainQueue] (origin, targets) {
     const queue = this[kQueue]
     let hasDispatcher = true
